// HookStateMachine.ts
// 黄金矿工钩子状态机实现

type HookState = 'idle' | 'swinging' | 'firing' | 'reeling' | 'grabbing' | 'returning';

interface Position {
  x: number;
  y: number;
}

interface Item {
  id: string;
  value: number;
  weight: number;
  position: Position;
}

interface HookConfig {
  swingSpeed: number;
  fireSpeed: number;
  reelSpeed: number;
  maxLength: number;
  originX: number;
  originY: number;
}

class HookStateMachine {
  // 当前状态
  private state: HookState = 'idle';

  // 位置信息
  private position: Position = { x: 0, y: 0 };
  private origin: Position = { x: 0, y: 0 };

  // 摆动角度
  private swingAngle: number = 0;
  private swingDirection: number = 1;

  // 抓取物
  private grabbedItem: Item | null = null;

  // 配置
  private config: HookConfig;

  // 状态持续时间/计时器
  private stateTimer: number = 0;

  // 回调函数
  private onStateChange?: (from: HookState, to: HookState) => void;
  private onItemCaught?: (item: Item) => void;
  private onReturned?: () => void;

  constructor(config: Partial<HookConfig> = {}) {
    this.config = {
      swingSpeed: 2,
      fireSpeed: 8,
      reelSpeed: 5,
      maxLength: 300,
      originX: 400,
      originY: 100,
      ...config
    };

    this.origin = {
      x: this.config.originX,
      y: this.config.originY
    };
    this.position = { ...this.origin };
  }

  // ========== 状态进入逻辑 ==========
  private onEnterState(newState: HookState): void {
    console.log(`[状态进入] ${newState}`);

    switch (newState) {
      case 'idle':
        this.position = { ...this.origin };
        this.grabbedItem = null;
        this.stateTimer = 0;
        break;

      case 'swinging':
        this.swingAngle = -Math.PI / 3; // 从-60度开始
        this.swingDirection = 1;
        break;

      case 'firing':
        // 记录发射时的角度
        break;

      case 'grabbing':
        this.stateTimer = 10; // 抓取动画持续10帧
        break;

      case 'reeling':
        // 开始回收
        break;

      case 'returning':
        // 回到原点后的处理
        break;
    }
  }

  // ========== 状态退出逻辑 ==========
  private onExitState(oldState: HookState): void {
    console.log(`[状态退出] ${oldState}`);

    switch (oldState) {
      case 'idle':
        // 准备摆动
        break;

      case 'swinging':
        // 锁定当前角度用于发射
        break;

      case 'firing':
        // 检查是否碰到物品
        break;

      case 'grabbing':
        // 抓取完成，开始回收
        break;

      case 'reeling':
        // 回收完成
        if (this.grabbedItem && this.onItemCaught) {
          this.onItemCaught(this.grabbedItem);
        }
        break;

      case 'returning':
        // 一轮结束
        if (this.onReturned) {
          this.onReturned();
        }
        break;
    }
  }

  // ========== 状态切换 ==========
  private transitionTo(newState: HookState): void {
    const oldState = this.state;
    this.onExitState(oldState);
    this.state = newState;
    this.onEnterState(newState);

    if (this.onStateChange) {
      this.onStateChange(oldState, newState);
    }
  }

  // ========== 每帧更新 ==========
  update(deltaTime: number = 1): void {
    switch (this.state) {
      case 'idle':
        // 空闲状态，等待开始
        break;

      case 'swinging':
        this.updateSwinging(deltaTime);
        break;

      case 'firing':
        this.updateFiring(deltaTime);
        break;

      case 'grabbing':
        this.updateGrabbing(deltaTime);
        break;

      case 'reeling':
        this.updateReeling(deltaTime);
        break;

      case 'returning':
        this.updateReturning(deltaTime);
        break;
    }
  }

  // 摆动状态：左右摆动
  private updateSwinging(deltaTime: number): void {
    const swingRange = Math.PI / 2; // ±90度
    const speed = this.config.swingSpeed * 0.02 * deltaTime;

    this.swingAngle += speed * this.swingDirection;

    // 边界检测：到达极限时反转方向
    if (this.swingAngle >= swingRange / 2) {
      this.swingAngle = swingRange / 2;
      this.swingDirection = -1;
    } else if (this.swingAngle <= -swingRange / 2) {
      this.swingAngle = -swingRange / 2;
      this.swingDirection = 1;
    }

    // 更新钩子位置（在原点附近摆动）
    const ropeLength = 50;
    this.position.x = this.origin.x + Math.sin(this.swingAngle) * ropeLength;
    this.position.y = this.origin.y + Math.cos(this.swingAngle) * ropeLength;
  }

  // 发射状态：向外延伸
  private updateFiring(deltaTime: number): void {
    const dx = Math.sin(this.swingAngle) * this.config.fireSpeed * deltaTime;
    const dy = Math.cos(this.swingAngle) * this.config.fireSpeed * deltaTime;

    this.position.x += dx;
    this.position.y += dy;

    // 边界检测：到达最大长度或触碰到物品
    const distance = Math.sqrt(
      Math.pow(this.position.x - this.origin.x, 2) +
      Math.pow(this.position.y - this.origin.y, 2)
    );

    if (distance >= this.config.maxLength) {
      // 到达最大长度，开始回收
      this.transitionTo('reeling');
    }
  }

  // 抓取状态：抓取动画
  private updateGrabbing(deltaTime: number): void {
    this.stateTimer -= deltaTime;

    if (this.stateTimer <= 0) {
      this.transitionTo('reeling');
    }
  }

  // 回收状态：带着物品返回
  private updateReeling(deltaTime: number): void {
    const dx = this.origin.x - this.position.x;
    const dy = this.origin.y - this.position.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance <= this.config.reelSpeed * deltaTime) {
      // 已回到原点
      this.position = { ...this.origin };
      this.transitionTo('returning');
    } else {
      // 向原点移动
      const ratio = (this.config.reelSpeed * deltaTime) / distance;
      this.position.x += dx * ratio;
      this.position.y += dy * ratio;

      // 更新抓取物位置
      if (this.grabbedItem) {
        this.grabbedItem.position = { ...this.position };
      }
    }
  }

  // 返回状态：处理结算
  private updateReturning(deltaTime: number): void {
    // 短暂停留后回到待命
    this.stateTimer += deltaTime;
    if (this.stateTimer >= 5) { // 5帧后重置
      this.transitionTo('idle');
    }
  }

  // ========== 玩家输入 ==========
  // 开始摆动
  startSwinging(): void {
    if (this.state === 'idle') {
      this.transitionTo('swinging');
    }
  }

  // 发射钩子
  fire(): void {
    if (this.state === 'swinging') {
      this.transitionTo('firing');
    }
  }

  // 触发抓取
  triggerGrab(item: Item): void {
    if (this.state === 'firing') {
      this.grabbedItem = item;
      this.transitionTo('grabbing');
    }
  }

  // ========== 边界情况处理 ==========

  // 强制重置（游戏结束/新关卡）
  forceReset(): void {
    this.grabbedItem = null;
    this.transitionTo('idle');
  }

  // 丢弃当前抓取物（使用道具）
  dropItem(): void {
    if (this.grabbedItem && (this.state === 'reeling' || this.state === 'grabbing')) {
      this.grabbedItem = null;
      this.transitionTo('reeling');
    }
  }

  // 加速回收（道具效果）
  speedUpReel(multiplier: number): void {
    if (this.state === 'reeling') {
      this.config.reelSpeed *= multiplier;
    }
  }

  // ========== 获取器 ==========
  getState(): HookState {
    return this.state;
  }

  getPosition(): Position {
    return { ...this.position };
  }

  getGrabbedItem(): Item | null {
    return this.grabbedItem;
  }

  getSwingAngle(): number {
    return this.swingAngle;
  }

  // 设置回调
  setOnStateChange(callback: (from: HookState, to: HookState) => void): void {
    this.onStateChange = callback;
  }

  setOnItemCaught(callback: (item: Item) => void): void {
    this.onItemCaught = callback;
  }

  setOnReturned(callback: () => void): void {
    this.onReturned = callback;
  }
}

// ========== 使用示例 ==========
function demo(): void {
  const hook = new HookStateMachine({
    originX: 400,
    originY: 100,
    maxLength: 300
  });

  // 设置回调
  hook.setOnStateChange((from, to) => {
    console.log(`状态变化: ${from} -> ${to}`);
  });

  hook.setOnItemCaught((item) => {
    console.log(`抓到物品: ${item.id}, 价值: ${item.value}`);
  });

  hook.setOnReturned(() => {
    console.log('钩子返回，准备下一轮');
  });

  // 模拟游戏流程
  console.log('=== 开始游戏 ===');

  // 1. 开始摆动
  hook.startSwinging();
  for (let i = 0; i < 60; i++) {
    hook.update();
  }

  // 2. 发射
  hook.fire();
  for (let i = 0; i < 20; i++) {
    hook.update();

    // 模拟碰撞检测
    if (i === 15) {
      const mockItem: Item = {
        id: 'gold_nugget',
        value: 100,
        weight: 1,
        position: hook.getPosition()
      };
      hook.triggerGrab(mockItem);
    }
  }

  // 3. 抓取和回收
  while (hook.getState() !== 'idle') {
    hook.update();
  }

  console.log('=== 一轮结束 ===');
}

// 运行演示
demo();

export { HookStateMachine, HookState, Position, Item, HookConfig };

