// 修复后的代码

// 定义Item接口
interface Item {
  id: string;
  value: number;
  weight: number;
}

// 使用枚举定义状态，避免硬编码错误
enum HookState {
  IDLE = 'idle',
  SWINGING = 'swinging',
  FIRING = 'firing',
  REELING = 'reeling',
  GRABBING = 'grabbing'
}

class Hook {
  // 原点位置
  private originX: number = 0;
  private originY: number = 0;

  // 当前位置
  x: number = 0;
  y: number = 0;

  // 当前状态
  state: HookState = HookState.IDLE;

  // 摆动相关
  private swingAngle: number = 0;
  private swingDirection: number = 1;
  private readonly swingSpeed: number = 0.05;
  private readonly maxSwingAngle: number = Math.PI / 3; // 60度

  // 发射相关
  private fireAngle: number = 0;
  private readonly fireSpeed: number = 10;
  private readonly maxLength: number = 300;

  // 回收相关
  private readonly reelSpeed: number = 8;

  // 抓取的物品
  private grabbedItem: Item | null = null;

  constructor(originX: number = 0, originY: number = 0) {
    this.originX = originX;
    this.originY = originY;
    this.x = originX;
    this.y = originY;
  }

  // 开始摆动
  startSwing(): void {
    if (this.state === HookState.IDLE) {
      this.state = HookState.SWINGING;
      this.swingAngle = -this.maxSwingAngle;
    }
  }

  // 发射钩子
  fire(): void {
    if (this.state === HookState.SWINGING) {
      this.state = HookState.FIRING;
      this.fireAngle = this.swingAngle;
    }
  }

  // 更新方法
  update(deltaTime: number = 1): void {
    switch (this.state) {
      case HookState.SWINGING:
        this.updateSwinging(deltaTime);
        break;

      case HookState.FIRING:
        this.updateFiring(deltaTime);
        break;

      case HookState.REELING:
        this.updateReeling(deltaTime);
        break;

      case HookState.GRABBING:
        // 抓取动画完成后进入回收
        this.state = HookState.REELING;
        break;
    }
  }

  // 摆动状态更新
  private updateSwinging(deltaTime: number): void {
    // 使用固定步长，保证不同帧率下速度一致
    this.swingAngle += this.swingSpeed * this.swingDirection * deltaTime;

    // 边界检测和反转
    if (this.swingAngle >= this.maxSwingAngle) {
      this.swingAngle = this.maxSwingAngle;
      this.swingDirection = -1;
    } else if (this.swingAngle <= -this.maxSwingAngle) {
      this.swingAngle = -this.maxSwingAngle;
      this.swingDirection = 1;
    }

    // 更新位置（基于原点）
    const ropeLength = 50;
    this.x = this.originX + Math.sin(this.swingAngle) * ropeLength;
    this.y = this.originY + Math.cos(this.swingAngle) * ropeLength;
  }

  // 发射状态更新
  private updateFiring(deltaTime: number): void {
    // 沿当前角度发射
    this.x += Math.sin(this.fireAngle) * this.fireSpeed * deltaTime;
    this.y += Math.cos(this.fireAngle) * this.fireSpeed * deltaTime;

    // 检查是否到达最大长度
    const distance = Math.sqrt(
      Math.pow(this.x - this.originX, 2) +
      Math.pow(this.y - this.originY, 2)
    );

    if (distance >= this.maxLength) {
      // 未抓到东西，直接回收
      this.state = HookState.REELING;
    }
  }

  // 回收状态更新
  private updateReeling(deltaTime: number): void {
    // 计算到原点的向量
    const dx = this.originX - this.x;
    const dy = this.originY - this.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    if (distance <= this.reelSpeed * deltaTime) {
      // 已回到原点
      this.x = this.originX;
      this.y = this.originY;
      this.state = HookState.IDLE;

      // 处理抓到的物品
      if (this.grabbedItem) {
        console.log(`获得物品: ${this.grabbedItem.id}, 价值: ${this.grabbedItem.value}`);
        this.grabbedItem = null;
      }
    } else {
      // 向原点移动
      const ratio = (this.reelSpeed * deltaTime) / distance;
      this.x += dx * ratio;
      this.y += dy * ratio;
    }
  }

  // 抓取物品
  catch(item: Item): void {
    if (this.state === HookState.FIRING) {
      this.grabbedItem = item;
      this.state = HookState.GRABBING;
    }
  }

  // 获取当前抓取的物品
  getGrabbedItem(): Item | null {
    return this.grabbedItem;
  }

  // 获取当前状态
  getState(): HookState {
    return this.state;
  }
}

export { Hook, HookState, Item };
